        recommends
            0 <= tid < self.req_len(),
    {
        match self {
            CombinerState::Collecting(reqs) => reqs[tid as int].is_some(),
            CombinerState::Responding(reqs, _) => reqs[tid as int].is_some(),
        }
    }
}

